import { validationResult } from 'express-validator';
import ApiError from '../utils/ApiError.js';

/**
 * Middleware that checks for validation errors generated by express-validator rules.
 * If errors are present, it wraps them into a 400 Bad Request ApiError and interrupts the request lifecycle.
 */
const validate = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    const extractedErrors = [];
    errors.array().map((err) => extractedErrors.push({ [err.path || err.param]: err.msg }));
    const firstErrorMessage = errors.array()[0]?.msg || 'Please check input parameters.';

    throw new ApiError(400, `Validation Failed: ${firstErrorMessage}`, extractedErrors);
  }
  next();
};

export default validate;
